<template>
 <div class="tutorial-coach" data-tutorial-coach :data-step="step" @keydown.stop @keyup.stop>
  <svg class="coach-shade" :width="viewport.w" :height="viewport.h" aria-hidden="true"><defs><mask :id="maskId"><rect width="100%" height="100%" fill="white"/><rect v-if="rect" :x="rect.x" :y="rect.y" :width="rect.w" :height="rect.h" rx="12" fill="black"/></mask></defs><rect width="100%" height="100%" fill="#081c2d" fill-opacity=".64" :mask="`url(#${maskId})`"/><rect v-if="rect" :x="rect.x" :y="rect.y" :width="rect.w" :height="rect.h" rx="12" fill="none" stroke="#e4c77e" stroke-width="2"/></svg>
  <div v-for="(block,i) in blockers" :key="i" class="coach-blocker" :style="block" @pointerdown.prevent @click.prevent />
  <section ref="card" class="coach-card" :style="position" role="dialog" :aria-labelledby="maskId+'-title'" aria-live="polite">
   <div class="coach-heading"><span>PREMIERS PAS</span><small>{{ number }} / 8</small></div>
   <h3 :id="maskId+'-title'">{{ copy.title }}</h3><p>{{ copy.text }}</p>
   <p v-if="error" class="coach-error" role="alert">{{ error }}</p>
   <footer><span v-if="copy.interactive" class="coach-hint"><i/>{{ copy.hint }}</span><button v-else :disabled="busy" @click="$emit('next')">{{ busy?'Enregistrement…':step==='care'?'C’est compris':'Continuer' }} <b aria-hidden="true">→</b></button></footer>
  </section>
 </div>
</template>
<script>
const messages={
 hp:{title:'La barre de vie',text:'Les PV sont les points de vie de ton Pokémon. Les attaques font baisser cette barre. À 0 PV, il est K.O. et ne peut plus combattre.'},
 potential:{title:'L’étoile de potentiel',text:'L’étoile représente le potentiel K, de 1 à 4. Il amplifie l’influence des IV sur les statistiques : un potentiel élevé aide ton Pokémon à devenir plus fort. Il ne remplace pas les niveaux ni l’entraînement.'},
 types:{title:'Les types font la différence',text:'Chaque Pokémon et chaque capacité ont un type. L’Eau est efficace contre le Feu, par exemple. À l’inverse, les attaques Électrik ne touchent pas les Pokémon Sol. Regarde les types avant de choisir !'},
 actions:{title:'Une action à chaque tour',text:'Attaque permet de choisir une capacité. Le Sac contient tes Balls. Pokémon permet de changer de compagnon, et Fuite de quitter une rencontre sauvage. Commençons par attaquer.'},
 attack:{title:'Ta première attaque',text:'Choisis Attaque, puis une capacité. Tu verras ton Pokémon agir et la barre de vie adverse diminuer.',interactive:true,hint:'À toi de jouer'},
 capture_info:{title:'Un nouveau compagnon',text:'Tu as effectué ta première action ! Affaiblir un Pokémon facilite sa capture. Ouvre le Sac et lance une Poké Ball : cette première capture est garantie.'},
 capture:{title:'Lance ta Poké Ball',text:'Ouvre le Sac, puis sélectionne la Poké Ball. Le Pokémon capturé rejoindra ton équipe.',interactive:true,hint:'Utilise la Poké Ball'},
 care:{title:'Prends soin de ton équipe',text:'Si tous tes Pokémon sont K.O., tu seras ramené à l’abri. Ta maman ou l’infirmière d’un Centre Pokémon peuvent soigner ton équipe. Tu peux maintenant retourner voir Wayne !'}
};
export default{props:{step:String,selector:String,busy:Boolean,error:String},data:()=>({rect:null,viewport:{w:0,h:0},cardHeight:220}),computed:{maskId(){return 'tutorial-mask-'+this._uid;},copy(){return messages[this.step]||messages.hp;},number(){return ['hp','potential','types','actions','attack','capture_info','capture','care'].indexOf(this.step)+1;},position(){const {w,h}=this.viewport,width=Math.min(350,Math.max(240,w-24));let top=this.rect?this.rect.y+this.rect.h+14:(h-this.cardHeight)/2;if(top+this.cardHeight>h-12)top=this.rect?this.rect.y-this.cardHeight-14:12;top=Math.max(12,Math.min(h-this.cardHeight-12,top));const left=Math.max(12,Math.min(w-width-12,this.rect?this.rect.x+this.rect.w/2-width/2:(w-width)/2));return{left:left+'px',top:top+'px',width:width+'px'};},blockers(){const r=this.rect;if(!r||!this.copy.interactive)return[{inset:0}];return[{left:0,top:0,width:'100%',height:r.y+'px'},{left:0,top:r.y+'px',width:r.x+'px',height:r.h+'px'},{left:r.x+r.w+'px',top:r.y+'px',right:0,height:r.h+'px'},{left:0,top:r.y+r.h+'px',width:'100%',bottom:0}];}},
 watch:{step(){this.$nextTick(()=>{this.measure();this.focusStep();});},selector(){this.$nextTick(this.measure);}},
 mounted(){this._resize=new ResizeObserver(()=>this.measure());this._resize.observe(document.documentElement);this._resize.observe(this.$refs.card);window.addEventListener('resize',this.measure);window.addEventListener('scroll',this.measure,true);this.$nextTick(()=>{this.measure();this.focusStep();});},
 beforeDestroy(){this._resize?.disconnect();window.removeEventListener('resize',this.measure);window.removeEventListener('scroll',this.measure,true);},
 methods:{focusStep(){if(!this.copy.interactive)this.$refs.card?.querySelector('button')?.focus({preventScroll:true});},measure(){const w=window.innerWidth,h=window.innerHeight;this.viewport={w,h};this.cardHeight=this.$refs.card?.offsetHeight||220;const target=this.selector&&document.querySelector(this.selector),r=target?.getBoundingClientRect();this.rect=r&&r.width&&r.height?{x:Math.max(4,r.left-5),y:Math.max(4,r.top-5),w:Math.min(w-8,r.width+10),h:Math.min(h-8,r.height+10)}:null;}}
};
</script>
<style scoped>
.tutorial-coach{position:fixed;inset:0;z-index:5200;pointer-events:none;color:var(--journal-ink);font:13px/1.55 var(--journal-font)}.coach-shade{position:absolute;inset:0;pointer-events:none}.coach-blocker{position:absolute;pointer-events:auto;touch-action:none}.coach-card{position:absolute;box-sizing:border-box;pointer-events:auto;padding:19px 20px 15px;border:2px solid var(--journal-border);border-top:4px solid #c5a966;border-radius:12px;background:var(--journal-paper);box-shadow:0 10px 40px #07162466;animation:coach-in .2s ease-out}.coach-heading{display:flex;justify-content:space-between;gap:15px;color:var(--journal-muted);font-size:9px;font-weight:700;letter-spacing:.12em}.coach-heading small{font-size:10px;letter-spacing:0}.coach-card h3{font:700 22px/1.2 Georgia,serif;color:var(--journal-heading);margin:9px 0}.coach-card p{margin:0 0 15px}.coach-card footer{display:flex;justify-content:flex-end;min-height:38px}.coach-card button{display:flex;align-items:center;justify-content:space-between;gap:20px;border:1px solid var(--journal-border);border-radius:6px;background:var(--journal-accent);color:var(--journal-on-accent);min-height:44px;padding:8px 13px;font:700 12px var(--journal-font);cursor:pointer}.coach-card button:focus-visible{outline:3px solid #dec278;outline-offset:3px}.coach-card button:disabled{opacity:.6}.coach-hint{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--journal-muted)}.coach-hint i{width:6px;height:6px;border-radius:50%;background:#c5a966}.coach-error{color:var(--journal-danger);font-size:11px}@keyframes coach-in{from{opacity:0;translate:0 5px}to{opacity:1;translate:0 0}}@media(max-height:520px){.coach-card{padding:12px 15px;font-size:11px;line-height:1.4}.coach-card h3{font-size:18px;margin:5px 0}.coach-card p{margin-bottom:8px}}@media(prefers-reduced-motion:reduce){.coach-card{animation:none}}
</style>
